<template><div class="page-heading"><div><span class="eyebrow">ACTIVITY & TRACEABILITY</span><h1>流转审计</h1><p>回看谁在什么时间，推动了一次设备交接。</p></div><el-button @click="load" :loading="loading"><Icon name="refresh" /> 刷新记录</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb20" /><section class="panel"><el-table :data="items" v-loading="loading" empty-text="暂无流转记录"><el-table-column label="操作时间" min-width="165"><template #default="{ row }">{{ dateTime(row.created_at) }}</template></el-table-column><el-table-column label="操作者" min-width="110"><template #default="{ row }">{{ row.actor_name || '—' }}</template></el-table-column><el-table-column label="操作内容" min-width="130"><template #default="{ row }"><span class="cell-title">{{ row.label || actions[row.action] || row.action }}</span></template></el-table-column><el-table-column label="申请 / 对象" min-width="155"><template #default="{ row }"><router-link v-if="row.request_id || row.request" :to="`/requests/${row.request_id || row.request}`" class="text-link">{{ row.request_number || row.number || `申请 #${row.request_id || row.request}` }}</router-link><span v-else>{{ row.asset_code || '设备记录' }}</span></template></el-table-column><el-table-column label="流转结果" min-width="150"><template #default="{ row }">{{ requestStates[row.to_status] || row.to_status || '—' }}</template></el-table-column><el-table-column prop="reason" label="处理说明" min-width="180" show-overflow-tooltip /></el-table><div class="pagination"><el-pagination :current-page="page" :page-size="20" :total="count" layout="total, prev, pager, next" @current-change="value => { page = value; load() }" /></div></section><div class="context-note"><Icon name="shield" /> 流转记录用于业务追溯，不提供编辑或删除入口。</div></template>
<script setup>
import { ref, onMounted } from 'vue'
import { get, rows } from '../api/client'
import { actions, requestStates, dateTime } from '../utils/format'
import Icon from '../ui/Icon.vue'
const items = ref([]), count = ref(0), page = ref(1), error = ref(''), loading = ref(false)
async function load() { loading.value = true; error.value = ''; try { const data = await get('audit/', { page: page.value }); items.value = rows(data); count.value = data.count ?? items.value.length } catch (e) { error.value = e.userMessage } finally { loading.value = false } }
onMounted(load)
</script>
